/**
 * Procedural noise texture
 *
 * bpy.types.WoodTexture
 */
export interface WoodTexture extends R.Texture {
  /** Scaling for noise input Range: 0.00009999999747378752 to inf. Default: 0.25. */
  get noise_scale(): H.Ref<number>;
  set noise_scale(v: H.In<number>);
  /** Turbulence of the bandnoise and ringnoise types Range: 0.00009999999747378752 to inf. Default: 5.0. */
  get turbulence(): H.Ref<number>;
  set turbulence(v: H.In<number>);
  /** Noise basis used for turbulence Default: 'BLENDER_ORIGINAL'. */
  get noise_basis(): H.Ref<E.CloudsTextureNoiseBasis>;
  set noise_basis(v: H.In<E.CloudsTextureNoiseBasis>);
  /**
   * Noise Type Default: 'SOFT_NOISE'.
   * - `SOFT_NOISE`: Soft (Generate soft noise (smooth transitions))
   * - `HARD_NOISE`: Hard (Generate hard noise (sharp transitions))
   */
  get noise_type(): H.Ref<"SOFT_NOISE" | "HARD_NOISE">;
  set noise_type(v: H.In<"SOFT_NOISE" | "HARD_NOISE">);
  /**
   * Pattern Default: 'BANDS'.
   * - `BANDS`: Bands (Use standard wood texture in bands)
   * - `RINGS`: Rings (Use wood texture in rings)
   * - `BANDNOISE`: Band Noise (Add noise to standard wood)
   * - `RINGNOISE`: Ring Noise (Add noise to rings)
   */
  get wood_type(): H.Ref<"BANDS" | "RINGS" | "BANDNOISE" | "RINGNOISE">;
  set wood_type(v: H.In<"BANDS" | "RINGS" | "BANDNOISE" | "RINGNOISE">);
  /**
   * Noise Basis 2 Default: 'SIN'.
   * - `SIN`: Sine (Use a sine wave to produce bands)
   * - `SAW`: Saw (Use a saw wave to produce bands)
   * - `TRI`: Tri (Use a triangle wave to produce bands)
   */
  get noise_basis_2(): H.Ref<"SIN" | "SAW" | "TRI">;
  set noise_basis_2(v: H.In<"SIN" | "SAW" | "TRI">);
  /** Size of derivative offset used for calculating normal Range: 0.0010000000474974513 to 0.10000000149011612. Default: 0.025. */
  get nabla(): H.Ref<number>;
  set nabla(v: H.In<number>);
}

