  set color(v: H.In<M.Color | readonly number[]>);
  /** World lighting settings */
  get light_settings(): H.Own<R.WorldLighting>;
  /** World mist settings */
  get mist_settings(): H.Own<R.WorldMistSettings>;
  /** Node tree for node based worlds */
  get node_tree(): H.Ptr<R.NodeTree>;
  /** Use shader nodes to render the world Default: False. @deprecated Unused but kept for compatibility reasons. Setting the property has no effect, and getting it always returns True. (5, 0, 0) (6, 0, 0) */
  get use_nodes(): H.Ref<boolean>;
  set use_nodes(v: H.In<boolean>);
  /** Lightgroup that the world belongs to Default: "". */
  get lightgroup(): H.Ref<string>;
  set lightgroup(v: H.In<string>);
  /**
   * Resolution when baked to a texture Default: '1024'.
   * - `128`: 128
   * - `256`: 256
   * - `512`: 512
   * - `1024`: 1024
   * - `2048`: 2048
   * - `4096`: 4096
   */
  get probe_resolution(): H.Ref<"128" | "256" | "512" | "1024" | "2048" | "4096">;
  set probe_resolution(v: H.In<"128" | "256" | "512" | "1024" | "2048" | "4096">);
  /** If non-zero, the maximum value for world contribution that will be recorded inside the world light probe. The excess contribution is converted to a sun light. This reduces the light bleeding caused by very bright light sources. Range: 0 to inf. Default: 10.0. */
  get sun_threshold(): H.Ref<number>;
  set sun_threshold(v: H.In<number>);
  /** Angular diameter of the Sun as seen from the Earth Range: 0 to 3.1415927410125732. Default: 0.00918043. */
  get sun_angle(): H.Ref<number>;
  set sun_angle(v: H.In<number>);
  /** Enable sun shadow casting Default: True. */
  get use_sun_shadow(): H.Ref<boolean>;
  set use_sun_shadow(v: H.In<boolean>);
  /** Maximum size of a shadow map pixel. Higher values use less memory at the cost of shadow quality. Range: 0 to inf. Default: 0.001. */
  get sun_shadow_maximum_resolution(): H.Ref<number>;
  set sun_shadow_maximum_resolution(v: H.In<number>);
