  get sun_shadow_filter_radius(): H.Ref<number>;
  set sun_shadow_filter_radius(v: H.In<number>);
  /** Enable jittered soft shadows to increase shadow precision (disabled in viewport unless enabled in the render settings). Has a high performance impact. Default: False. */
  get use_sun_shadow_jitter(): H.Ref<boolean>;
  set use_sun_shadow_jitter(v: H.In<boolean>);
  /** Apply shadow tracing to each jittered sample to reduce under-sampling artifacts Range: 0 to 100. Default: 10.0. */
  get sun_shadow_jitter_overblur(): H.Ref<number>;
  set sun_shadow_jitter_overblur(v: H.In<number>);
